#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin>>n;
    vector<int> K(n);
    vector<vector<pair<int,int>>> orig(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>K[i]; orig[i].resize(K[i]);
        for(int j=0;j<K[i];j++) cin>>orig[i][j].first>>orig[i][j].second;
        totalCells+=K[i];
    }
    struct Ori{vector<pair<int,int>> cells;int w,h,f,r;};
    vector<vector<Ori>> allOris(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                vector<pair<int,int>> tc;
                for(auto [ox,oy]:orig[i]){
                    int x=ox,y=oy;
                    if(f) x=-x;
                    for(int q=0;q<r;q++){int t=x;x=-y;y=t;}
                    tc.push_back({x,y});
                }
                int mnx=INT_MAX,mny=INT_MAX;
                for(auto&[x,y]:tc){mnx=min(mnx,x);mny=min(mny,y);}
                for(auto&[x,y]:tc){x-=mnx;y-=mny;}
                sort(tc.begin(),tc.end());
                if(seen.insert(tc).second){
                    int w=0,h=0;
                    for(auto[x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                    allOris[i].push_back({tc,w,h,f,r});
                }
            }
        }
    }
    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return K[a]>K[b];});
    int sqA=max(1,(int)ceil(sqrt((double)totalCells)));
    int bestArea=INT_MAX; struct Pl{int x,y,r,f;};
    vector<Pl> bestPl(n); int bestW=0,bestH=0;
    for(int W=max(1,sqA/2);W<=sqA*3;W++){
        int gridH=totalCells/max(1,W)+n*10+100;
        vector<int> hm(W,0);
        vector<vector<bool>> grid(W,vector<bool>(gridH,false));
        vector<Pl> pl(n); int maxY=0; bool fail=false;
        for(int idx=0;idx<n&&!fail;idx++){
            int pi=order[idx]; int bs=INT_MAX,bx=-1,by=-1,boi=-1;
            for(int oi=0;oi<(int)allOris[pi].size();oi++){
                auto&o=allOris[pi][oi]; if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){
                    int my=0; for(auto[cx,cy]:o.cells) my=max(my,hm[x+cx]-cy);
                    if(my<0)my=0;
                    for(int y=my;y<min(gridH-o.h+1,my+10);y++){
                        bool ok=true;int top=0;
                        for(auto[cx,cy]:o.cells){if(grid[x+cx][y+cy]){ok=false;break;}top=max(top,y+cy+1);}
                        if(!ok)continue;
                        int sc=top*10000+y*100+x;
                        if(sc<bs){bs=sc;bx=x;by=y;boi=oi;}
                        break;
                    }
                }
            }
            if(bx<0){fail=true;break;}
            auto&o=allOris[pi][boi];
            for(auto[cx,cy]:o.cells){grid[bx+cx][by+cy]=true;hm[bx+cx]=max(hm[bx+cx],by+cy+1);maxY=max(maxY,by+cy+1);}
            pl[pi]={bx,by,o.r,o.f};
        }
        if(fail)continue;
        int area=W*maxY;
        if(area<bestArea){bestArea=area;bestW=W;bestH=maxY;bestPl=pl;}
    }
    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
